/// <summary>
/// COC of SalesConfirmDP
/// </summary>
[ExtensionOf(classStr(SalesConfirmDP))]
final class AVASalesConfirmDPCls_Extension
{
}

Method.Source:
/// <summary>
/// delete the orignial header. Save the markup before deletion
/// </summary>
/// <param name = "_salesConfirmHeaderTmp">_salesConfirmHeaderTmp</param>
protected void deleteCopiedHeader(SalesConfirmHeaderTmp _salesConfirmHeaderTmp)
{
    //copy of the salesInvoicetmp from UsingExistingReportData()
    AvaReportingMarkupTransTmp::copyMarkupTrans(_salesConfirmHeaderTmp.TableId, _salesConfirmHeaderTmp.AVAOrigSalesConfirmHeaderTmp, _salesConfirmHeaderTmp.RecId);

    next deleteCopiedHeader(_salesConfirmHeaderTmp);
}

/// <summary>
/// delete the orignial details. Save the markup before deletion
/// </summary>
/// <param name = "_salesConfirmHeaderTmp">_salesConfirmHeaderTmp</param>
protected void deleteCopiedLines(SalesConfirmHeaderTmp _salesConfirmHeaderTmp)
{

    SalesConfirmDetailsTmp  salesConfirmDetailsTmp;

    while select salesConfirmDetailsTmp        //the created data is copied so it should be deleted.
        where salesConfirmDetailsTmp.CreatedTransactionId == _salesConfirmHeaderTmp.CreatedTransactionId
    {
        //copy of the salesInvoicetmp from UsingExistingReportData()
        AvaReportingMarkupTransTmp::copyMarkupTrans(salesConfirmDetailsTmp.TableId, salesConfirmDetailsTmp.AVAOrigSalesConfirmDetailsTmp, salesConfirmDetailsTmp.RecId);
    }
    next deleteCopiedLines(_salesConfirmHeaderTmp);
}

    /// <summary>
/// Initializes a sales order confirmation header.
/// </summary>
/// <returns>
/// The initialized <c>SalesConfirmHeaderTmp</c> sales order confirmation header record.
/// </returns>
protected SalesConfirmHeaderTmp initializeSalesOrderConfirmationHeader()
{
    SalesConfirmHeaderTmp salesConfirmHeaderTmp = next initializeSalesOrderConfirmationHeader();
    // Set the AVAOrigSalesConfirmHeaderTmp field to the current record's RecId
    salesConfirmHeaderTmp.AVADlvMode = this.parmCustConfirmJour().DlvMode;
    salesConfirmHeaderTmp.AVADlvTerm = this.parmCustConfirmJour().DlvTerm;
    salesConfirmHeaderTmp.AVAWorkerSalesTaker = this.parmCustConfirmJour().WorkerSalesTaker;

    return salesConfirmHeaderTmp;
}

/// <summary>
/// Initializes a sales order confirmation line.
/// </summary>
/// <param name = "_salesConfirmHeaderTmp">
/// A <c>SalesConfirmHeaderTmp</c> record which is the sales order confirmation header.
/// </param>
/// <param name = "_confirmationLineSelection">
/// A <c>SalesConfirmDPConfirmationLineQuerySelection</c> object which the sales order confirmation line should be initialized from.
/// </param>
/// <returns>
/// The initialized <c>SalesConfirmDetailsTmp</c> sales order confirmation line record.
/// </returns>
protected SalesConfirmDetailsTmp initializeSalesOrderConfirmationLine(
    SalesConfirmHeaderTmp                           _salesConfirmHeaderTmp,
    SalesConfirmDPConfirmationLineQuerySelection    _confirmationLineSelection)
{
    CustConfirmTrans custConfirmTrans = _confirmationLineSelection.parmCustConfirmTrans();
    SalesLine salesLine = custConfirmTrans.salesLine();
    InventTable inventTable = custConfirmTrans.inventTable();

    SalesConfirmDetailsTmp salesConfirmDetailsTmp = next initializeSalesOrderConfirmationLine(_salesConfirmHeaderTmp, _confirmationLineSelection);
    // Set the AVAOrigSalesConfirmDetailsTmp field to the current record's RecId
    salesConfirmDetailsTmp.AVALineNum = custConfirmTrans.LineNum;
    salesConfirmDetailsTmp.AVACustomerLineNum = salesLine.CustomerLineNum;
    salesConfirmDetailsTmp.AVAPriceUnit = custConfirmTrans.PriceUnit;
    salesConfirmDetailsTmp.AVAOrigCountryRegionId = inventTable.OrigCountryRegionId;
    return salesConfirmDetailsTmp;
}
